func (sh *shaping) converse(ctx context.Context, input []any) (outcome, provider.Usage, error) {
var usage provider.Usage
sinceSubmit := 0
var reads readMemory
for {
revision, err := CurrentRevision(sh.repo)
if err != nil {
return outcome{}, usage, err
}
if _, err := sh.writeManifest(revision); err != nil {
return outcome{}, usage, err
}
req := provider.Request{Role: ProviderRole(sh.role), Instructions: ShaperInstructions(), Input: input, Tools: sh.toolDefs,
Scope: sh.ev.Dir, Context: map[string]any{"phase": "shape", "role": "shape", "slug": sh.slug}}
call := sh.ev.BeginCall("shape", "", revision.Map(), "main shaping", sh.role).Sized(sh.client, req)
resp, err := sh.client.Respond(ctx, sh.s, req, call)
call.End(resp, err)
if err != nil {
return outcome{}, usage, err
}
calls := tools.Calls(resp.Items)
input = append(input, tools.Replay(resp.Items)...)
if len(calls) == 0 {
if sinceSubmit++; shapeAnswerLimit(sinceSubmit) {
return noToolStop(lastSubmission{}, ""), usage, nil
}
input = append(input, map[string]any{"role": "user", "content": "Call a tool."})
continue
}
var outputs []any
for _, group := range batchGroups(calls) {
if readOnlyCall(group[0].Name) {
outs, err := sh.runReadOnly(ctx, group, &reads)
if err != nil {
return outcome{}, usage, err
}
outputs = append(outputs, outs...)
continue
}
c := group[0]
var out any
if c.Name == ProposeFilesTool {
out, err = sh.proposeFiles(c.Args())
} else {
out, err = sh.runTool(ctx, c)
}
if err != nil {
return outcome{}, usage, err
}
outputs = append(outputs, toolOutput(c, out))
}
input = append(input, outputs...)
}
}
