package shape
import "github.com/KogenAI/kogen-loop/tools"
const batchSentence = "Request every independent read_file, search_text, list_files and probe call you need in one response, and do not re-read a file you have already read unless it changed."
func readOnlyCall(name string) bool {
return name == tools.ReadFileTool || name == tools.SearchTextTool || name == tools.ListFilesTool
}
// batchGroups: runs of consecutive read-only calls, and every other call alone, in order.
func batchGroups(calls []tools.Call) [][]tools.Call {
var groups [][]tools.Call
for _, c := range calls {
if n := len(groups); n > 0 && readOnlyCall(c.Name) && readOnlyCall(groups[n-1][0].Name) {
groups[n-1] = append(groups[n-1], c)
continue
}
groups = append(groups, []tools.Call{c})
}
return groups
}

