package shape
import (
"context"
"sync"
"github.com/KogenAI/kogen-loop/tools"
)
// runReadOnly runs a group of read-only calls concurrently and records them in call order.
func (sh *shaping) runReadOnly(ctx context.Context, group []tools.Call, mem *readMemory) ([]any, error) {
outs := make([]tools.Output, len(group))
errs := make([]error, len(group))
err := sh.toolSpan(func() error {
tl := sh.agentTools(ctx, sh.mainTools())
var wg sync.WaitGroup
for i, c := range group {
wg.Add(1)
go func() {
defer wg.Done()
outs[i], errs[i] = tl.Run(c.Name, c.Args())
}()
}
wg.Wait()
for _, e := range errs {
if e != nil {
return e
}
}
return nil
})
if err != nil {
return nil, err
}
var outputs []any
for i, c := range group {
out := outs[i]
sh.noteReach(c.Name, c.Args())
if c.Name == tools.ReadFileTool {
if sh.readTexts == nil {
sh.readTexts = map[string]string{}
}
path, _ := c.Args()["path"].(string)
sh.readTexts[cleanCitedPath(path)] = out.Text
out = mem.answer(len(sh.window.history), c.Args(), out)
}
sh.noteTool(c.Name, out)
outputs = append(outputs, toolOutput(c, out))
}
return outputs, nil
}

