package shape
import (
"crypto/sha256"
"encoding/hex"
"fmt"
"strings"
"github.com/KogenAI/kogen-loop/tools"
)
// readMemory is what the read_file calls of the current working window returned.
type readMemory struct {
generation int
texts      map[string]string
}
// answer is the result the shaper receives for a read_file result out.
func (m *readMemory) answer(generation int, args map[string]any, out tools.Output) tools.Output {
if m.texts == nil || m.generation != generation {
m.generation, m.texts = generation, map[string]string{}
}
if strings.HasPrefix(out.Text, "error: ") {
return out
}
path, _ := args["path"].(string)
key := fmt.Sprintf("%s\x00%v\x00%v", cleanCitedPath(path), args["start_line"], args["end_line"])
if prev, ok := m.texts[key]; ok && prev == out.Text {
sum := sha256.Sum256([]byte(out.Text))
return tools.Output{Text: fmt.Sprintf("already read in this window, unchanged (%d bytes, sha %s)", len(out.Text), hex.EncodeToString(sum[:])[:8])}
}
m.texts[key] = out.Text
return out
}

