// batchDefinitions adds the batching instruction to the read, search, list and probe tools.
func batchDefinitions(defs []map[string]any) []map[string]any {
for i, d := range defs {
if name, _ := d["name"].(string); readOnlyCall(name) || name == ProbeTool {
d = maps.Clone(d)
d["description"] = d["description"].(string) + " " + batchSentence
defs[i] = d
}
}
return defs
}

